361	/// Trim prefix ASCII spaces from the given slice and return the corresponding
362	/// range.
363	///
364	/// This stops trimming a prefix as soon as it sees non-whitespace or a line
365	/// terminator.
366	pub fn trim_ascii_prefix(
367	    line_term: LineTerminator,
368	    slice: &[u8],
369	    range: Match,
370	) -> Match {
371	    fn is_space(b: u8) -> bool {
372	        match b {
373	            b'\t' | b'\n' | b'\x0B' | b'\x0C' | b'\r' | b' ' => true,
374	            _ => false,
375	        }
376	    }
377	
378	    let count = slice[range]
379	        .iter()
380	        .take_while(|&&b| -> bool {
381	            is_space(b) && !line_term.as_bytes().contains(&b)
382	        })
383	        .count();
384	    range.with_start(range.start() + count)
385	}
