387	pub fn find_iter_at_in_context<M, F>(
388	    searcher: &Searcher,
389	    matcher: M,
390	    mut bytes: &[u8],
391	    range: std::ops::Range<usize>,
392	    mut matched: F,
393	) -> io::Result<()>
394	where
395	    M: Matcher,
396	    F: FnMut(Match) -> bool,
397	{
398	    // This strange dance is to account for the possibility of look-ahead in
399	    // the regex. The problem here is that mat.bytes() doesn't include the
400	    // lines beyond the match boundaries in mulit-line mode, which means that
401	    // when we try to rediscover the full set of matches here, the regex may no
402	    // longer match if it required some look-ahead beyond the matching lines.
403	    //
404	    // PCRE2 (and the grep-matcher interfaces) has no way of specifying an end
405	    // bound of the search. So we kludge it and let the regex engine search the
406	    // rest of the buffer... But to avoid things getting too crazy, we cap the
407	    // buffer.
408	    //
409	    // If it weren't for multi-line mode, then none of this would be needed.
410	    // Alternatively, if we refactored the grep interfaces to pass along the
411	    // full set of matches (if available) from the searcher, then that might
412	    // also help here. But that winds up paying an upfront unavoidable cost for
413	    // the case where matches don't need to be counted. So then you'd have to
414	    // introduce a way to pass along matches conditionally, only when needed.
415	    // Yikes.
416	    //
417	    // Maybe the bigger picture thing here is that the searcher should be
418	    // responsible for finding matches when necessary, and the printer
419	    // shouldn't be involved in this business in the first place. Sigh. Live
420	    // and learn. Abstraction boundaries are hard.
421	    let is_multi_line = searcher.multi_line_with_matcher(&matcher);
422	    if is_multi_line {
423	        if bytes[range.end..].len() >= MAX_LOOK_AHEAD {
424	            bytes = &bytes[..range.end + MAX_LOOK_AHEAD];
425	        }
426	    } else {
427	        // When searching a single line, we should remove the line terminator.
